@triton.jit
def _bce_compute(x, y, w, p, HAS_WEIGHT: tl.constexpr, HAS_POS: tl.constexpr):
    lg = tl.log(1.0 + tl.exp(-tl.abs(x)))
    if HAS_POS:
        sp = tl.maximum(-x, 0.0) + lg
        logw = (p - 1.0) * y + 1.0
        L = (1.0 - y) * x + logw * sp
    else:
        # (1-y)*x + max(-x,0) == max(x,0) - y*x  (x + max(-x,0) == max(x,0))
        L = tl.maximum(x, 0.0) - y * x + lg
    if HAS_WEIGHT:
        L = L * w
    return L


