    partials = torch.empty(M, dtype=torch.float32, device=self.device)
    _bce_reduce_kernel[grid](
        self_f,
        target_f,
        weight_f,
        pos_f,
        partials,
        N,
        HAS_WEIGHT=HAS_WEIGHT,
        HAS_POS=HAS_POS,
        BLOCK=BLOCK,
    )
    out = torch.empty((), dtype=self.dtype, device=self.device)
    scale = (1.0 / N) if reduction == 1 else 1.0
    FBLOCK = triton.next_power_of_2(max(M, 1))
